-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["ae1f65480fe57e45"] = { "Quando è tutto pronto, premi il detonatore.\n\nHo garantito un segnale forte facendo passare fili di rame e d'argento, con una schiera di antenne Melthusian, dentro l'involucro della scatola. Dovrebbe darti una buona portata. Fai solo attenzione ai goblin nei dintorni. Non apprezzeranno la mia creazione, se ti vedono.\n\nAh, nel caso non fosse ovvio: non stare vicino al carro quando salta in aria... fa male.", "." },
  ["ae445e6c5653a024"] = { "Lothar e i suoi guerrieri, di ritorno da Karazhan, speravano di arginare la perdita di vite e di salvare la loro patria un tempo gloriosa. Invece tornarono troppo tardi e trovarono il loro amato regno ridotto a rovine fumanti. L'⟦Horde=Orda⟧ degli orchi continuò a devastare le campagne e reclamò per sé le terre circostanti. Costretti a nascondersi, Lothar e i suoi compagni fecero il cupo giuramento di riconquistare la loro patria a qualunque costo.", "." },
  ["ae6373dc5de2a8d1"] = { "L'⟦Hand of Dagun=Artiglio di Dagun⟧\n\nDagun è una creatura delle acque profonde, venerata dai murloc di ⟦Dustwallow Marsh=Acquemorte⟧. Lo attirano in superficie con una speciale alga marina, incantata dai loro sciamani. Caccia i murloc, raccogli la loro alga incantata, poi posala sull'altare dei murloc. Dagun arriverà, e tu lo starai aspettando.\n\nVoglio quell'artiglio.", "." },
  ["ae86d7a51c183814"] = { "La terza fazione, il clan ⟦Dark Iron=Ferroscuro⟧, era guidata dal thane stregone Thaurissan. I ⟦Dark Iron=Ferroscuro⟧ si nascondevano nelle ombre più profonde sotto la montagna e tramavano contro i loro cugini, sia i Barbabronzea sia i Granmartello.", "." },
  ["ae8d63d48953f5f4"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI DEGLI UFFICIALI DELL'ORDA</H1><BR/>\n<P align=\"center\">Parte 2</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">Centurione</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">Legionario</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">Guardia di Sangue</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">Guardia di Pietra</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["aead5bb0f75b4b97"] = { "Il fallimento degli orchi nel conquistare il mondo per la Legione Infuocata costrinse Kil'jaeden a creare un nuovo esercito per seminare il caos in tutti i regni di Azeroth. Questo nuovo esercito non doveva cadere preda delle stesse meschine rivalità e lotte interne che avevano afflitto l'⟦Horde=Orda⟧. Avrebbe dovuto essere spietato e risoluto nella sua missione. Questa volta Kil'jaeden non poteva permettersi di fallire.", "." },
  ["aeecfc8b64580dfa"] = { "Questi fregi incisi a rilievo sono forse il ritrovamento più importante delle prime sale di Uldaman. Le incisioni suggeriscono chiaramente un legame tra i terrigeni, simili a golem, e la razza dei nani. Se dovessero emergere altre prove, le teorie sulla nostra presunta creazione da parte dei mitici Titani potrebbero rivelarsi vere.", "." },
})
